from datetime import date, datetime
from decimal import Decimal, InvalidOperation
import re


def aging_buckets(invoices: list[dict], as_of: date) -> dict[str, Decimal]:
    if isinstance(as_of, datetime):
        as_of_date = as_of.date()
    elif isinstance(as_of, date):
        as_of_date = as_of
    elif isinstance(as_of, str):
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", as_of) is None:
            raise ValueError("invalid as_of date")
        try:
            as_of_date = date.fromisoformat(as_of)
        except ValueError:
            raise ValueError("invalid as_of date") from None
    else:
        raise ValueError("invalid as_of date")

    if invoices is None:
        raise ValueError("invalid invoices")

    buckets = {
        "current": Decimal("0.00"),
        "1-30": Decimal("0.00"),
        "31-60": Decimal("0.00"),
        "61-90": Decimal("0.00"),
        "90+": Decimal("0.00"),
    }

    for invoice in invoices:
        if not isinstance(invoice, dict):
            raise ValueError("invalid invoice")
        if "due_date" not in invoice or "amount" not in invoice:
            raise ValueError("missing invoice key")

        due_raw = invoice["due_date"]
        if isinstance(due_raw, datetime):
            due_date = due_raw.date()
        elif isinstance(due_raw, date):
            due_date = due_raw
        elif isinstance(due_raw, str):
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", due_raw) is None:
                raise ValueError("invalid due_date")
            try:
                due_date = date.fromisoformat(due_raw)
            except ValueError:
                raise ValueError("invalid due_date") from None
        else:
            raise ValueError("invalid due_date")

        amount_raw = invoice["amount"]
        if isinstance(amount_raw, bool) or isinstance(amount_raw, float):
            raise ValueError("invalid amount")
        if isinstance(amount_raw, Decimal):
            amount = amount_raw
        elif isinstance(amount_raw, int):
            amount = Decimal(amount_raw)
        elif isinstance(amount_raw, str):
            try:
                amount = Decimal(amount_raw)
            except (InvalidOperation, ValueError):
                raise ValueError("invalid amount") from None
        else:
            raise ValueError("invalid amount")
        if not amount.is_finite():
            raise ValueError("invalid amount")

        days_overdue = (as_of_date - due_date).days
        if days_overdue <= 0:
            key = "current"
        elif days_overdue <= 30:
            key = "1-30"
        elif days_overdue <= 60:
            key = "31-60"
        elif days_overdue <= 90:
            key = "61-90"
        else:
            key = "90+"
        buckets[key] += amount

    return {key: value.quantize(Decimal("0.01")) for key, value in buckets.items()}
